3	// Regression coverage for the byte offsets carried by character-integrity
4	// failures. A consumer of the per-line failure records gets one error string
5	// with an "at byte offset N" position; these tests pin what N means so the
6	// consumer can slice the raw input at N and land exactly on the corruption:
7	//
8	//   - N is a zero-based byte offset into the line content AFTER the legal
9	//     JSON document whitespace (space, tab, CR, LF) around the object is
10	//     trimmed — not an offset into the whole input stream, and not a
11	//     terminal display column.
12	//   - N counts raw input bytes: Chinese text, emoji, and legal escape
13	//     sequences before the corruption contribute their on-the-wire byte
14	//     length, never a display character count or a decoded string length,
15	//     and nested unknown-field content is located from the line start, not
16	//     from the field value or an inner object.
17	//   - Invalid UTF-8 points at the first byte that cannot form a legal
18	//     character (the start of a truncated multi-byte sequence); an unpaired
19	//     surrogate escape points at the backslash opening the escape, and the
20	//     message distinguishes a lone high surrogate from a lone low one.
21	//   - Correctly paired escapes and plain "uD800" text behind an escaped
22	//     backslash are not corruption and must not shift the offset of a real
23	//     problem later in the same line; invalid UTF-8 outranks an unpaired
24	//     escape even when the escape sits earlier in the line.
25	//
26	// The tests only observe NormalizeReader's public records; the normalization
27	// behavior itself is unchanged.
28	
29	import (
30		"bytes"
31		"regexp"
32		"strconv"
33		"strings"
34		"testing"
35		"unicode/utf8"
36	)
37	
38	// byteOffsetPattern extracts the position a character-integrity failure
39	// reports for its corruption point.
40	var byteOffsetPattern = regexp.MustCompile(`at byte offset ([0-9]+)`)
41	
42	// reportedOffset parses the byte offset out of a failure record's error,
43	// failing the test when the error carries no position.
44	func reportedOffset(t *testing.T, msg string) int {
45		t.Helper()
46		m := byteOffsetPattern.FindStringSubmatch(msg)
47		if m == nil {
48			t.Fatalf("error %q must carry an \"at byte offset N\" position", msg)
49		}
50		offset, err := strconv.Atoi(m[1])
51		if err != nil {
52			t.Fatalf("parsing offset from %q: %v", msg, err)
53		}
54		return offset
55	}
56	
57	// trimJSONDocumentWhitespace mirrors the normalizer's own trimming, so tests
58	// can express expectations against the same content the offset counts from:
59	// the JSON document on the line, without the legal whitespace around it.
60	func trimJSONDocumentWhitespace(line string) []byte {
61		return bytes.Trim([]byte(line), " \t\r\n")
62	}
63	
64	// requireOffsetPointsAt asserts the reported offset is exactly the byte
65	// index of marker within the trimmed line content: a consumer slicing the
66	// raw input at the reported position lands on the corruption itself.
67	func requireOffsetPointsAt(t *testing.T, trimmed []byte, offset int, marker string) {
68		t.Helper()
69		want := bytes.Index(trimmed, []byte(marker))
70		if want < 0 {
71			t.Fatalf("test bug: marker %q not found in %q", marker, trimmed)
72		}
73		if offset != want {
74			t.Fatalf("offset must locate %q at byte %d of the trimmed line content, got %d", marker, want, offset)
75		}
76		if !bytes.HasPrefix(trimmed[offset:], []byte(marker)) {
77			t.Fatalf("slicing the input at offset %d must land on %q, got %q", offset, marker, trimmed[offset:])
78		}
79	}
80	
81	// expectOffsetFailure normalizes input as a one-line stream and requires
82	// exactly one failure record — line 1, ok:false, one error, no event — whose
83	// error carries a byte offset. It returns the error message and the offset.
84	func expectOffsetFailure(t *testing.T, input string) (string, int) {
85		t.Helper()
86		var out bytes.Buffer
87		failures, err := NormalizeReader(strings.NewReader(input), &out)
88		if err != nil {
89			t.Fatalf("a corrupted log line is not a stream error, got %v", err)
90		}
91		if failures != 1 {
92			t.Fatalf("the corrupted line must count as one failure, got %d", failures)
93		}
94		if !utf8.Valid(out.Bytes()) {
95			t.Fatalf("output must be valid UTF-8 even for corrupted input: %q", out.Bytes())
96		}
97		results := decodeResults(t, out.Bytes())
98		if len(results) != 1 {
99			t.Fatalf("expected exactly one result, got %#v", results)
100		}
101		r := results[0]
102		if r["line"] != float64(1) || r["ok"] != false {
103			t.Fatalf("the corrupted line must fail as line 1: %#v", r)
104		}
105		if _, exists := r["event"]; exists {
106			t.Fatalf("a character-corrupted line must not emit an event: %#v", r)
107		}
108		msg, _ := r["error"].(string)
109		if msg == "" {
110			t.Fatalf("the failure record must explain itself: %#v", r)
111		}
112		return msg, reportedOffset(t, msg)
113	}
114	
115	// The offset counts from the first byte of the JSON document on the line:
116	// spaces, tabs, and carriage returns around the object are trimmed away and
117	// must not move the reported position of the same corruption point, while
118	// the same characters between tokens inside the object occupy real bytes and
119	// do move it.
120	func TestNormalizeOffsetStartsAtTrimmedLineContent(t *testing.T) {
121		corrupted := `{"timestamp":"2026-01-02T00:00:00Z","action":"\uD800"}`
122		base := bytes.Index([]byte(corrupted), []byte(`\uD800`))
123	
124		variants := []struct {
125			name  string
126			input string
127		}{
128			{"no surrounding whitespace", corrupted},
129			{"leading space", " " + corrupted},
130			{"leading tabs", "\t\t" + corrupted},
131			{"leading carriage return", "\r" + corrupted},
132			{"mixed leading and trailing whitespace", " \t\r" + corrupted + " \t"},
133			{"leading spaces and trailing carriage return", "  " + corrupted + "\r"},
134		}
135		for _, tc := range variants {
136			t.Run(tc.name, func(t *testing.T) {
137				msg, offset := expectOffsetFailure(t, tc.input+"\n")
138				if !strings.Contains(msg, "unpaired") {
139					t.Fatalf("expected an unpaired escape failure, got %q", msg)
140				}
141				if offset != base {
142					t.Fatalf("whitespace around the object must not move the offset %d, got %d", base, offset)
143				}
144				requireOffsetPointsAt(t, trimJSONDocumentWhitespace(tc.input), offset, `\uD800`)
145			})
146		}
147	
148		t.Run("whitespace inside the object still occupies bytes", func(t *testing.T) {
149			// Two extra spaces after "{" and one tab before "action" sit inside
150			// the document: the same corruption point moves by exactly those
151			// three bytes. The tab counts as one byte, not a display column.
152			spaced := "{  \"timestamp\":\"2026-01-02T00:00:00Z\",\t\"action\":\"\\uD800\" }"
153			_, offset := expectOffsetFailure(t, spaced+"\n")
154			if offset != base+3 {
155				t.Fatalf("internal whitespace must count as bytes: want offset %d, got %d", base+3, offset)
156			}
157			requireOffsetPointsAt(t, trimJSONDocumentWhitespace(spaced), offset, `\uD800`)
158		})
159	}
160	
161	// Content before the corruption point contributes its raw input byte length:
162	// Chinese characters are three bytes each, an emoji four, and a legal
163	// \uXXXX escape six — never a display character count and never the length
164	// of the string those bytes decode to.
165	func TestNormalizeOffsetCountsInputBytesNotCharacters(t *testing.T) {
166		cases := []struct {
167			name           string
168			action         string
169			marker         string
170			multibyteAhead bool // raw multi-byte characters precede the corruption
171		}{
172			{"Chinese text before the bad escape", `登录\uD800`, `\uD800`, true},
173			{"emoji before the bad escape", `😀\uDC00`, `\uDC00`, true},
174			// A legal BMP escape is six raw bytes decoding to one character; the
175			// bad escape sits after those six bytes, not after one.
176			{"legal BMP escape before the bad escape", `\u0041\uD800`, `\uD800`, false},
177			// A paired surrogate escape is twelve raw bytes decoding to a single
178			// astral character; neither twelve-to-one nor twelve-to-four
179			// rewrites may apply.
180			{"paired surrogate escape before the bad escape", `\uD83D\uDE00\uD800`, `\uD800`, false},
181		}
182		for _, tc := range cases {
183			t.Run(tc.name, func(t *testing.T) {
184				input := `{"timestamp":"2026-01-02T00:00:00Z","action":"` + tc.action + `"}`
185				_, offset := expectOffsetFailure(t, input+"\n")
186				trimmed := trimJSONDocumentWhitespace(input)
187				requireOffsetPointsAt(t, trimmed, offset, tc.marker)
188				if tc.multibyteAhead {
189					if runes := utf8.RuneCount(trimmed[:offset]); runes == offset {
190						t.Fatalf("offset %d must count bytes, not display characters", offset)
191					}
192				}
193			})
194		}
195	}
