197	// Corruption inside an unknown field's nested object or array is located
198	// from the start of the whole line, exactly like corruption in a mapped
199	// field — never re-anchored to the field value or to the inner object.
200	func TestNormalizeOffsetInNestedExtraIsLineRelative(t *testing.T) {
201		t.Run("unpaired escape deep in a nested object", func(t *testing.T) {
202			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a","extra":{"deep":["ok","\uD800"]}}`
