249					t.Fatalf("expected an invalid UTF-8 failure, got %q", msg)
250				}
251				if strings.Contains(msg, "surrogate") {
252					t.Fatalf("UTF-8 corruption must not be reported as an escape problem, got %q", msg)
253				}
254				requireOffsetPointsAt(t, trimJSONDocumentWhitespace(tc.input), offset, tc.marker)
255			})
256		}
257	}
