303	// Legal lookalikes are neither flagged themselves nor miscounted: a
304	// correctly paired surrogate escape, plain "uD800" text behind an escaped
305	// backslash, and a literal U+FFFD leave the offset of a real corruption
306	// later in the same line exactly at that corruption's own byte index.
307	func TestNormalizeLegalLookalikesDoNotShiftCorruptionOffset(t *testing.T) {
308		t.Run("unpaired escape after legal lookalikes", func(t *testing.T) {
309			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"ok",` +
310				`"pair":"\uD83D\uDE00","text":"\\uD800","mark":"�","bad":"\uDC00"}`
311			msg, offset := expectOffsetFailure(t, input+"\n")
312			if !strings.Contains(msg, "unpaired") || !strings.Contains(msg, "low surrogate") {
313				t.Fatalf("the lone low surrogate must be the reported problem, got %q", msg)
314			}
315			requireOffsetPointsAt(t, trimJSONDocumentWhitespace(input), offset, `\uDC00`)
316		})
317		t.Run("invalid UTF-8 after legal lookalikes", func(t *testing.T) {
318			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"ok",` +
319				`"pair":"\uD83D\uDE00","text":"\\uD800","bad":"` + "\xff" + `"}`
320			msg, offset := expectOffsetFailure(t, input+"\n")
321			if !strings.Contains(msg, "UTF-8") {
322				t.Fatalf("the invalid byte must be the reported problem, got %q", msg)
323			}
324			requireOffsetPointsAt(t, trimJSONDocumentWhitespace(input), offset, "\xff")
325		})
326	}
